/**
 * FEAT-118 — El freno de contexto: cuándo avisar que conviene un handoff, el
 * estado de la fila de la banda y su texto. Puro: `mods.tsx` pone las
 * mediciones, el reloj y el botón.
 *
 * El porcentaje es contra la ventana de compactación (la del autocompact), no
 * contra la del modelo: contra esa, un 80 % puede llegar tarde.
 */

import { duracion } from './banda-texto.ts'

export const UMBRALES = [70, 85] as const
/** Por debajo de esto (tras compactar) los umbrales se rearman: un aviso por ciclo de compactación. */
export const REARME = 40
/** Lo que se ve «Handoff guardado» o el error. */
export const VISIBLE_MS = 20_000
const EXITO = 'Resumen (handoff) guardado en '

export type FaseHandoff = 'quieto' | 'generando' | 'listo' | 'error'

export type Handoff = {
  /** Umbrales ya avisados en este ciclo. */
  disparados: number[]
  /** El umbral del aviso visible, o `null` (sin aviso o descartado). */
  aviso: number | null
  /** El último porcentaje medido. */
  pct: number | null
  fase: FaseHandoff
  /** Inicio de `generando`. */
  desde: number
  /** El texto de `listo` o `error`. */
  texto: string
  /** Cuándo vence `listo` o `error`. */
  hasta: number
}

export type FilaHandoff = { texto: string; tono: 'aviso' | 'urgente' | 'normal' | 'ok' | 'error'; botones: boolean }

export function nuevoHandoff(): Handoff {
  return { disparados: [], aviso: null, pct: null, fase: 'quieto', desde: 0, texto: '', hasta: 0 }
}

/** Porcentaje entero de `tokens` sobre `ventana`, o `null` sin datos. */
export function pctDe(tokens: unknown, ventana: unknown): number | null {
  if (typeof tokens !== 'number' || typeof ventana !== 'number' || !Number.isFinite(tokens) || !Number.isFinite(ventana) || tokens < 0 || ventana <= 0) return null
  return Math.round((tokens / ventana) * 100)
}

/**
 * Una medición nueva. Cruzar un umbral no avisado lo avisa (el más alto
 * cruzado, marcando también los de abajo); bajar de `REARME` rearma todo y
 * quita el aviso. Nada más cambia.
 */
export function medir(h: Handoff, pct: number | null): Handoff {
  if (pct === null) return h
  if (pct < REARME) return { ...h, disparados: [], aviso: null, pct }
  const cruzados = UMBRALES.filter((u) => pct >= u)
  const nuevo = cruzados.filter((u) => !h.disparados.includes(u))
  if (!nuevo.length) return { ...h, pct }
  return { ...h, pct, disparados: [...new Set([...h.disparados, ...cruzados])], aviso: Math.max(...nuevo) }
}

/** «Ahora no»: oculta el aviso; vuelve con el próximo umbral o el próximo ciclo. */
export function descartar(h: Handoff): Handoff {
  return { ...h, aviso: null }
}

export function empezar(h: Handoff, ahora: number): Handoff {
  return { ...h, aviso: null, fase: 'generando', desde: ahora, texto: '' }
}

/** `~` en lugar del home, para que la fila no muestre la carpeta del usuario entera. */
export function conTilde(ruta: string, home: string): string {
  const r = ruta.replace(/\\/g, '/')
  const h = home.replace(/\\/g, '/').replace(/\/+$/, '')
  return h && r.toLowerCase().startsWith(h.toLowerCase() + '/') ? '~' + r.slice(h.length) : r
}

/** El fin de `/lagrange-resumen handoff si`: de su texto, solo la primera línea (el pie de costo no va). */
export function terminar(h: Handoff, texto: string, ahora: number, home: string): Handoff {
  const primera = String(texto ?? '').split(/\r?\n/)[0].trim()
  const ok = primera.startsWith(EXITO)
  const mostrado = ok ? `Handoff guardado en ${conTilde(primera.slice(EXITO.length).trim(), home)}` : primera || 'No se generó el handoff.'
  return { ...h, fase: ok ? 'listo' : 'error', texto: mostrado, hasta: ahora + VISIBLE_MS }
}

/** `listo` y `error` vencidos vuelven a `quieto`. */
export function vigente(h: Handoff, ahora: number): Handoff {
  return (h.fase === 'listo' || h.fase === 'error') && ahora >= h.hasta ? { ...h, fase: 'quieto', texto: '' } : h
}

/** ¿Hay fila de handoff que dibujar (y reloj que hacer avanzar)? */
export function hayAviso(h: Handoff, ahora: number): boolean {
  if (h.fase === 'generando') return true
  if (h.fase === 'listo' || h.fase === 'error') return ahora < h.hasta
  return h.aviso !== null
}

export function filaDeHandoff(h: Handoff, ahora: number): FilaHandoff | null {
  if (h.fase === 'generando') return { texto: `Generando handoff… ${duracion(ahora - h.desde)}`, tono: 'normal', botones: false }
  if ((h.fase === 'listo' || h.fase === 'error') && ahora < h.hasta) return { texto: h.texto, tono: h.fase === 'listo' ? 'ok' : 'error', botones: false }
  if (h.aviso === null) return null
  return { texto: `Contexto: ${h.pct ?? h.aviso} % hasta compactar`, tono: h.aviso >= 85 ? 'urgente' : 'aviso', botones: true }
}

files.hooks/bandeja-texto.ts:
/**
 * FEAT-115 + FEAT-116 — El buzón y el recall en la banda, sin `$`: qué
 * mensajes se ven, cómo se dibujan, y los textos que el plugin manda a Claude.
 *
 * El texto de un mensaje de otro agente se le muestra al USUARIO en la banda;
 * a Claude nunca le llega por acá: con «pasar a Claude» recibe el mismo aviso
 * de siempre (quién y cuántos) y lo lee con `mensaje leer`, dentro de su sobre.
 */

import type { MensajeBanda, NotaRespuesta, NovedadBanda } from '../types'
export type { MensajeBanda, NotaRespuesta, NovedadBanda }

/** BE-111 — El texto a enviar: el de onSubmit, salvo que lo guardado por onInput lo extienda (se perdió el final). */
export function textoFinal(enviado: string, guardado: string): string {
  return guardado.length > enviado.length && guardado.startsWith(enviado) ? guardado : enviado
}

/** Lo que se ve en la banda: los pendientes que el usuario no despachó en esta sesión. */
export function visibles(mensajes: readonly MensajeBanda[], listos: readonly string[]): MensajeBanda[] {
  const fuera = new Set(listos)
  return mensajes.filter((m) => m && typeof m.id === 'string' && m.id && !fuera.has(m.id))
}

/** `nodo/nombre`, o solo el nombre en el nodo local. */
export function remitente(m: MensajeBanda): string {
  return m.de.nodo && m.de.nodo !== 'local' ? `${m.de.nodo}/${m.de.nombre}` : m.de.nombre || 'otro agente'
}

const MAX_FILAS_TEXTO = 3

/** Las filas del primer mensaje: la cabecera y hasta tres líneas del texto. */
export function filasDeMensaje(m: MensajeBanda, mas: number): string[] {
  const lineas = m.texto.split('\n').map((l) => l.trim()).filter(Boolean)
  const cuerpo = lineas.slice(0, MAX_FILAS_TEXTO)
  if (lineas.length > MAX_FILAS_TEXTO) cuerpo[MAX_FILAS_TEXTO - 1] = `${cuerpo[MAX_FILAS_TEXTO - 1]} …`
  const resto = mas > 0 ? `  (+${mas} más)` : ''
  return [`✉ ${remitente(m)} · de otro agente${resto}`, ...cuerpo.map((l) => `  ${l}`)]
}

// El mismo saneo que `textoAviso` de `mcp-server/lib/buzones.js`: lo que diga otro nodo no entra crudo.
const limpio = (v: unknown) => String(v ?? '').replace(/[^A-Za-z0-9._/-]/g, '').slice(0, 81)

/** «Pasar a Claude»: el aviso de siempre, sin el texto. */
export function avisoParaClaude(m: MensajeBanda): string {
  return `📨 Tenés 1 mensaje de otros agentes (de ${limpio(m.de.nodo)}/${limpio(m.de.nombre)}). Leelo con la herramienta \`mensaje\`, accion: leer.`
}

/**
 * Lo que se antepone al próximo prompt del usuario después de responder desde
 * la banda: el texto es del propio usuario. Vacío si no hay notas.
 */
export function bloqueDeRespuestas(notas: readonly NotaRespuesta[]): string {
  if (!notas.length) return ''
  // El remitente y el id vienen de otro agente: saneados como en el aviso; el texto es del propio usuario.
  const filas = notas.map((n) => `- A ${limpio(n.de)} (mensaje ${limpio(n.id)}) le respondí desde la banda: «${n.texto}»`)
  return `[Mientras tanto, desde la banda de Lagrange]\n${filas.join('\n')}\nLos mensajes originales están en \`mensaje\` (accion: leer, todos: true).\n\n`
}

const CUENTA = /^[\w-]{1,40}$/

/** FEAT-116 — El pedido de «traer»: solo la cuenta (validada) y cuántas notas. Sin nombres de archivo. */
export function pedidoDeRecall(n: NovedadBanda): string | null {
  if (!CUENTA.test(n.cuenta)) return null
  const cuantas = `${n.cantidad} nota${n.cantidad === 1 ? '' : 's'}`
  return `Traé con la tool \`recall\` (desde: "${n.cuenta}") la memoria de esta cuenta para este proyecto: tiene ${cuantas} nuevas o cambiadas. Seguí la skill \`recall\`: compará con tu memoria, verificá contra el código y guardá solo lo que sirva, adaptado.`
}

/** FEAT-116 — La fila de la banda. */
export function filaDeNovedad(n: NovedadBanda): string {
  return `📚 ${n.nombre} tiene ${n.cantidad} nota${n.cantidad === 1 ? '' : 's'} nueva${n.cantidad === 1 ? '' : 's'} de este proyecto`
}

/** FEAT-116 — Del JSON de `recall-novedades.js` a filas: cantidad y la marca a guardar (el mtime más nuevo). */
export function novedadesDe(salida: unknown): NovedadBanda[] {
  const cuentas = (salida as { cuentas?: unknown } | null)?.cuentas
  if (!Array.isArray(cuentas)) return []
  const out: NovedadBanda[] = []
  for (const c of cuentas) {
    const notas = Array.isArray(c?.notas) ? c.notas.filter((x: { mtimeMs?: unknown }) => typeof x?.mtimeMs === 'number') : []
    if (typeof c?.cuenta !== 'string' || !CUENTA.test(c.cuenta) || !notas.length) continue
    const nombre = typeof c.nombre === 'string' && c.nombre.trim() ? c.nombre.trim().slice(0, 40) : c.cuenta
    const total = Number.isInteger(c.total) && c.total >= notas.length ? c.total : notas.length
    out.push({ cuenta: c.cuenta, nombre, cantidad: total, hasta: Math.max(...notas.map((x: { mtimeMs: number }) => x.mtimeMs)) })
  }
  return out
}

files.hooks/turno-texto.ts:
/**
 * FEAT-122 — La línea de tiempo del turno, sin `$`: qué se anota de cada tool
 * y de cada request, y cómo se dibuja (una tira por tool, el resumen por tipo
 * y la cabecera con tiempo, requests, tokens y costo).
 *
 * Solo el loop principal: la tool de un subagente no se cuenta aparte (su
 * tiempo es el de la tool `Agent` que lo lanzó). El costo es el del turno
 * entero (lo que sumó la sesión entre el inicio y el fin): repartirlo por tool
 * sería inventarlo.
 */
import { nombreCorto, duracion } from './banda-texto.ts'

// Locales: la línea de tiempo vive en una variable del mod (UI efímera), no en `$.state`.
export type ToolTurno = { nombre: string; desdeMs: number; duracionMs: number; error: boolean }
export type Tokens = { entrada: number; salida: number; cacheLeida: number; cacheEscrita: number }
export type TurnoCerrado = {
  turnId: string
  fin: number
  duracionMs: number
  interrumpido: boolean
  requests: number
  tokens: Tokens
  costo: number | null
  tools: ToolTurno[]
  extra: number
}

export const TOPE_TOOLS = 200
export const TOPE_FILAS = 25
export const TOPE_FILAS_PANEL = 8
export const TURNOS_GUARDADOS = 5
const ANCHO_BARRA = 40
const ANCHO_NOMBRE = 16

export type TurnoEnCurso = {
  turnId: string
  desde: number
  costoInicial: number | null
  tools: ToolTurno[]
  abiertas: Record<string, { nombre: string; desde: number }>
  extra: number
  requests: number
}

export function nuevoTurno(turnId: string, desde: number, costoInicial: number | null): TurnoEnCurso {
  return { turnId, desde, costoInicial, tools: [], abiertas: {}, extra: 0, requests: 0 }
}

export function abrirTool(t: TurnoEnCurso, clave: string, tool: string, ahora: number): void {
  t.abiertas[clave] = { nombre: nombreCorto(tool), desde: ahora }
}

export function cerrarTool(t: TurnoEnCurso, clave: string, ahora: number, error: boolean): void {
  const a = t.abiertas[clave]
  if (!a) return
  delete t.abiertas[clave]
  if (t.tools.length >= TOPE_TOOLS) { t.extra += 1; return }
  t.tools.push({ nombre: a.nombre, desdeMs: Math.max(0, a.desde - t.desde), duracionMs: Math.max(0, ahora - a.desde), error })
}

type Uso = { input_tokens?: number; output_tokens?: number; cache_read_input_tokens?: number; cache_creation_input_tokens?: number } | null | undefined

/** Solo cuenta: los tokens los trae sumados `turn.complete`. */
export function contarPaso(t: TurnoEnCurso): void {
  t.requests += 1
}

export function tokensDe(uso: Uso): Tokens {
  return {
    entrada: Number(uso?.input_tokens) || 0,
    salida: Number(uso?.output_tokens) || 0,
    cacheLeida: Number(uso?.cache_read_input_tokens) || 0,
    cacheEscrita: Number(uso?.cache_creation_input_tokens) || 0
  }
}

/** Cierra el turno: las tools que quedaron abiertas (interrumpidas) cuentan hasta el fin. */
export function cerrarTurno(t: TurnoEnCurso, { durationMs, interrumpido, costoFinal, ahora, uso }: { durationMs: number; interrumpido: boolean; costoFinal: number | null; ahora: number; uso: Uso }): TurnoCerrado {
  for (const clave of Object.keys(t.abiertas)) cerrarTool(t, clave, ahora, true)
  const costo = t.costoInicial !== null && costoFinal !== null ? Math.max(0, costoFinal - t.costoInicial) : null
  return { turnId: t.turnId, fin: ahora, duracionMs: Math.max(0, durationMs), interrumpido, requests: t.requests, tokens: tokensDe(uso), costo, tools: t.tools, extra: t.extra }
}

export function tokensCortos(n: number): string {
  if (n >= 1_000_000) return `${(n / 1_000_000).toFixed(1).replace('.', ',')}M`
  if (n >= 1000) return `${Math.round(n / 1000)}k`
  return String(n)
}

export function cabecera(t: TurnoCerrado): string {
  const total = t.tokens.entrada + t.tokens.salida + t.tokens.cacheLeida + t.tokens.cacheEscrita
  const costo = t.costo === null ? '—' : `$${t.costo.toFixed(2).replace('.', ',')}`
  const req = `${t.requests} request${t.requests === 1 ? '' : 's'}`
  return `Turno de ${duracion(t.duracionMs)} · ${req} · ${tokensCortos(total)} tokens (cache ${tokensCortos(t.tokens.cacheLeida)}) · ${costo}${t.interrumpido ? ' (interrumpido)' : ''}`
}

/** `░░░████░░░`: dónde empezó y cuánto duró, sobre el largo del turno; al menos una celda. */
export function barra(desdeMs: number, duracionMs: number, totalMs: number, ancho = ANCHO_BARRA): string {
  const total = Math.max(1, totalMs)
  const ini = Math.min(ancho - 1, Math.floor((desdeMs / total) * ancho))
  const largo = Math.max(1, Math.min(ancho - ini, Math.round((duracionMs / total) * ancho)))
  return '░'.repeat(ini) + '█'.repeat(largo) + '░'.repeat(ancho - ini - largo)
}

export type FilaTira = { texto: string; error: boolean }

/** Una tira por tool en orden de inicio; con más de 25, las 25 más largas y `+N más`. */
export function tiras(t: TurnoCerrado, tope = TOPE_FILAS): FilaTira[] {
  const total = Math.max(t.duracionMs, ...t.tools.map((x) => x.desdeMs + x.duracionMs))
  let elegidas = t.tools
  let fuera: ToolTurno[] = []
  if (t.tools.length > tope) {
    const largas = new Set([...t.tools].sort((a, b) => b.duracionMs - a.duracionMs).slice(0, tope))
    elegidas = t.tools.filter((x) => largas.has(x))
    fuera = t.tools.filter((x) => !largas.has(x))
  }
  // En orden de inicio: `tools` queda en orden de cierre (se anota al terminar cada una).
  elegidas = [...elegidas].sort((a, b) => a.desdeMs - b.desdeMs)
  const filas = elegidas.map((x) => ({ texto: `${x.nombre.slice(0, ANCHO_NOMBRE).padEnd(ANCHO_NOMBRE)} ${barra(x.desdeMs, x.duracionMs, total)} ${duracion(x.duracionMs)}`, error: x.error }))
  const resto = fuera.length + t.extra
  if (resto > 0) filas.push({ texto: `+${resto} más (${duracion(fuera.reduce((s, x) => s + x.duracionMs, 0))}${t.extra ? ', sin detalle' : ''})`, error: false })
  return filas
}

/** `Bash ×7 · 41s`, por tiempo total. */
export function porTipo(t: TurnoCerrado): string[] {
  const m = new Map<string, { n: number; ms: number }>()
  for (const x of t.tools) {
    const v = m.get(x.nombre) ?? { n: 0, ms: 0 }
    v.n += 1
    v.ms += x.duracionMs
    m.set(x.nombre, v)
  }
  return [...m.entries()].sort((a, b) => b[1].ms - a[1].ms).map(([n, v]) => `${n} ×${v.n} · ${duracion(v.ms)}`)
}

/** Los anteriores, del más nuevo al más viejo, en una línea. */
export function anteriores(turnos: readonly TurnoCerrado[]): string {
  return turnos.slice(0, -1).reverse().map((x) => duracion(x.duracionMs)).join(' · ')
}

/** Lo que responde `/turno`. */
export function textoDeTurno(turnos: readonly TurnoCerrado[]): string {
  const t = turnos[turnos.length - 1]
  // BE-108 — El historial vive en el mod: una recarga de plugins lo vacía, y un comando con / no es un turno.
  if (!t) return 'Todavía no hay turnos cerrados desde que cargó el mod (la recarga de plugins lo vacía; un comando con / no es un turno).'
  const previos = anteriores(turnos)
  return [cabecera(t), ...tiras(t).map((f) => (f.error ? `${f.texto} ✗` : f.texto)), '', `Por tipo: ${porTipo(t).join(' · ') || 'sin tools'}`, ...(previos ? [`Anteriores: ${previos}`] : [])].join(String.fromCharCode(10))
}

